INSERT INTO jhi_authority (name)
SELECT 'ROLE_SUPER_ADMIN'
WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name = 'ROLE_SUPER_ADMIN');

INSERT INTO jhi_authority (name)
SELECT 'ROLE_SALES'
WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name = 'ROLE_SALES');

INSERT INTO jhi_authority (name)
SELECT 'ROLE_OPERATIONS'
WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name = 'ROLE_OPERATIONS');

INSERT INTO jhi_authority (name)
SELECT 'ROLE_CUSTOMER_SUPPORT'
WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name = 'ROLE_CUSTOMER_SUPPORT');

INSERT INTO jhi_user_authority (user_id, authority_name)
SELECT u.id, 'ROLE_SUPER_ADMIN'
FROM jhi_user u
WHERE u.login = 'admin'
  AND NOT EXISTS (
      SELECT 1 FROM jhi_user_authority ua
      WHERE ua.user_id = u.id AND ua.authority_name = 'ROLE_SUPER_ADMIN'
  );
